from __future__ import absolute_import
import tempfile
import datetime
import os
from selenium.webdriver.common.by import By
from selenium.common.exceptions import TimeoutException
from selenium.webdriver.common.keys import Keys
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.common.action_chains import ActionChains
from taf.ul.oam.selenium_core.common import BasicPage
from taf.ul.oam.selenium_core.webdrivers import CustomWebdriver
from taf.ul.oam.selenium_core.download_tools import Downloader
from .utils import choose_selector_way


class LocalBasicPage(BasicPage):
    """
    Basic class, initializes web driver and provides common element operations functions.
    """
    def __init__(self, download_dir=None, screenshot_dir=None):
        self._web_driver = WebDriver(download_dir, screenshot_dir)
        super(LocalBasicPage, self).__init__(self._web_driver.driver)

    @property
    def driver(self):
        return self._web_driver.driver

    @property
    def _download_dir(self):
        return self._web_driver.download_dir

    @property
    def _downloader(self):
        return self._web_driver.downloader

    @property
    def debug_dir(self):
        return self._web_driver.debug_dir

    def close_browser(self):
        self._web_driver.close()

    def get_attribute_by_xpath(self, xpath, attr_name, timeout=60):
        self._wait_for_element_by((By.XPATH, xpath), timeout)
        return self.driver.find_element_by_xpath(xpath).get_attribute(attr_name)

    def get_text_by_xpath(self, xpath, timeout=60):
        self._wait_for_element_by((By.XPATH, xpath), timeout)
        return self.driver.find_element_by_xpath(xpath).text.strip()

    def get_text_by_xpath_if_exist(self, xpath, timeout=5, _out=""):
        """
        Variation of get_text_by_path. In comparison it not wait until timeout ends, but immediately after not finding
        element it throws NoSuchElementException.
        :param xpath: Path to element which we want to acquire.
        :param timeout: int, timeout
        :param _out: Message which we want to be returned
        :return: Message from xpath, or in case of NoSuchElementException - _out defined by user.
        """
        try:
            self._wait_for_element_by((By.XPATH, xpath), timeout)
            out = self.driver.find_element_by_xpath(xpath).text.strip()
        except TimeoutException:
            out = _out
        return out

    def get_elements_xpath_list(self, xpath, timeout=60):
        elements_xpath_list = []
        self.wait_for_visibility_by_xpath(xpath, timeout)
        elements = self.driver.find_elements_by_xpath(xpath)
        for idx in range(len(elements)):
            elements_xpath_list.append(xpath + '[{}]'.format(idx + 1))
        return elements_xpath_list

    def find_element_from_group_by_text(self, elements, text):
        """
        To find one element by text from group
        :param elements: list, list of WebElements
        :param text: str, text value of elements
        :return: WebElement or None
        """
        for element in elements:
            if text == element.text:
                return element
        return None

    def expand_dropdown_list_and_return_elements(self, button_locator, option_locator, timeout=60):
        """
        To expand dropdown list and return all elements
        :return: WebElement
        """
        self.click_enabled_element(button_locator, timeout)
        return self.driver.find_elements(*option_locator)

    def select_element_from_dropdown_list_by_text_and_click(self, element_text, button_locator,
                                                            option_locator, timeout=60):
        elements = self.expand_dropdown_list_and_return_elements(button_locator, option_locator, timeout)
        self.find_element_from_group_by_text(elements, element_text).click()

    @staticmethod
    def _clear_text_of_field(elem):
        elem.send_keys(Keys.CONTROL + 'a')
        elem.send_keys(Keys.BACKSPACE)

    def _insert_text_to_field(self, text, elem):
        """
        Clear text and input a new one
        """
        self._clear_text_of_field(elem)
        elem.send_keys(text)

    def _click_button(self, locator):
        self.driver.find_element(*locator).click()

    def insert_text_to_enable_element_and_enter(self, locator, text, timeout=60):
        """
        Insert text to enable element and click enter
        """
        self.wait_for_enable(locator, timeout)
        element = self.driver.find_element(*locator)
        self._insert_text_to_field(text, element)
        element.send_keys(Keys.ENTER)

    def insert_text_to_enable_element(self, locator, text, timeout=60):
        """
        Insert text to enable element
        :return: WebElement
        """
        self.wait_for_enable(locator, timeout)
        self._insert_text_to_field(text, self.driver.find_element(*locator))

    def clear_text_of_enable_element(self, locator, timeout=60):
        self.wait_for_enable(locator, timeout)
        element = self.driver.find_element(*locator)
        self._clear_text_of_field(element)

    def click_enabled_element(self, locator, timeout=60):
        self.wait_for_enable(locator, timeout)
        self._click_button(locator)

    def click_enabled_element_after_visible(self, locator, timeout=60):
        self.wait_for_visibility(locator, timeout)
        self.click_enabled_element(locator, timeout)

    def perform_element_hover_by_xpath(self, xpath):
        self.wait_for_visibility((By.XPATH, xpath))
        elem = self.driver.find_element_by_xpath(xpath)
        ActionChains(self.driver).move_to_element(elem).perform()

    def wait_for_new_window_open(self, current_handle, timeout=5):
        self._until(EC.new_window_is_opened(current_handle), timeout)

    def switch_to_coam_login_tab(self):
        """
        There are three ways to open a new tab or window:
        1. use web driver to execute js script(will open a new window):
            driver.execute_script("window.open('your url','_blank');")
        2. send combination of keys COMMAND + T or CTRL + T to open a new tab on one window(can't work on firefox):
            ActionChains(driver).key_down(Keys.CONTROL).send_keys('t').key_up(Keys.CONTROL).perform()
        3. 1) send combination of keys COMMAND + T or CTRL + T to one element(can't work on firefox)
            driver.find_element_by_tag_name('body').send_keys(Keys.CONTROL + 't')
           2) send key CTRL and click one element to open a new tab:
            ActionChains(self.driver).key_down(Keys.CONTROL).click(element).key_up(Keys.CONTROL).perform()
        """
        link_xpath = "//a[contains(text(), 'Manual')]"
        current_window_handle = self.driver.current_window_handle
        ActionChains(self.driver).key_down(Keys.CONTROL).\
            click(self.driver.find_element_by_xpath(link_xpath)).key_up(Keys.CONTROL).perform()
        self.wait_for_new_window_open([current_window_handle])
        for handle in self.driver.window_handles:
            if handle != current_window_handle:
                self.driver.switch_to_window(handle)

    def disable_screen_lock(self, time_interval=30000):
        """
        Method to disable screen lock after idle for some minutes
        :param time_interval: int, event execution time interval, 30000 is 30s
        """
        mouse_move_event_script = 'window.interval_id = setInterval(function(){var event = new Event("mousemove"); ' \
                                  'document.body.dispatchEvent(event);}, %d)' % time_interval
        self.driver.execute_script(mouse_move_event_script)

    def enable_screen_lock(self):
        """
        Method to enable screen lock after idle for some minutes
        """
        interval_id = self.driver.execute_script("return window.interval_id")
        self.driver.execute_script("clearInterval({})".format(interval_id))

    def save_screenshot(self, filename, screenshot_dir=None):
        screenshot_dir = screenshot_dir if screenshot_dir else self.debug_dir
        self.driver.save_screenshot('{}/{}_{}.png'.
                                    format(screenshot_dir, filename, datetime.datetime.now().strftime("%Y%m%d_%H%M%S")))

    def disable_message_box(self):
        try:
            self._wait_for_element_by((By.CLASS_NAME, "notifyjs-corner"), 30)
            self.hide_element("body > div[class=notifyjs-corner]")
        except TimeoutException:
            pass

    def refresh_page(self):
        """
        Refreshes page in web browser (same as pressing F5 key).
        """
        self.driver.refresh()

    def click_and_wait_for_corresponding_element_visible(self, click_element_xpath, corresponding_xpath,
                                                         index=0, timeout=60):
        self.wait_for_visibility((By.XPATH, click_element_xpath), timeout)
        self.click_element_by_xpath(click_element_xpath, index)
        self.wait_for_visibility((By.XPATH, corresponding_xpath), timeout)

    def select_radiobox_by_xpath(self, xpath, timeout=60):
        self.wait_for_enable((By.XPATH, xpath), timeout)
        self.driver.find_element_by_xpath(xpath).click()

    def wait_for_visibility_by_xpath(self, xpath, timeout=60):
        self.wait_for_visibility((By.XPATH, xpath), timeout)

    def download_files(self, start_time, download_timeout=1800):
        return self._downloader.download(download_dir=self._download_dir,
                                         start_downloading_time=start_time, download_timeout=download_timeout)

    def select_checkbox_by_specified_status(self, is_selected, select_xpath, click_xpath):
        """
        Some page of checkbox's click element is different of select element, so here parameters are separated, if your
        page of checkbox's click and select element are same, please input the same xpath value each.

        :param is_selected: bool, only support 'True' and 'False'
        :param select_xpath: str, it is used to check if checkbox can be selected,
        :param click_xpath: str, it is used to click checkbox
        :return:
        """
        self._wait_for_element_by((By.XPATH, select_xpath))
        if is_selected != self.driver.find_element_by_xpath(select_xpath).is_selected():
            self.driver.find_element_by_xpath(click_xpath).click()

    def get_dict_from_elements_by_xpath(self, key_xpath, value_xpath, separator=''):
        key_elements = self.driver.find_elements_by_xpath(key_xpath)
        value_elements = self.driver.find_elements_by_xpath(value_xpath)
        key_list = [item.text.strip(separator) for item in key_elements]
        value_list = [item.text for item in value_elements]
        return dict(zip(key_list, value_list))

    @choose_selector_way
    def display_element(self, select_element_script, *args, **kwargs):
        self.driver.execute_script(''.join([select_element_script, ".style.display='inline-block'"]))

    @choose_selector_way
    def hide_element(self, select_element_script, *args, **kwargs):
        self.driver.execute_script(''.join([select_element_script, ".style.display='none'"]))

    def load_file_from_hidden_button(self, button_location, button_xpath, file_path, timeout):
        """
        Actual load file button is hidden normally by developer, so we should show it , load file and then hide it

        :param button_location: str, hidden button unique location in web element
        :param button_xpath: str, hidden button's xpath
        :param file_path: str, load file's directory
        :param timeout: int, time to wait file loading
        :return:
        """
        self.display_element(button_location)
        self.wait_for_enable((By.XPATH, button_xpath), timeout)
        elem = self.driver.find_element_by_xpath(button_xpath)
        elem.clear()
        elem.send_keys(file_path)
        self.hide_element(button_location)

    def wait_for_text_present_in_attribute(self, xpath, attr_name, text, timeout=60):
        self._until(lambda x: text in self.get_attribute_by_xpath(xpath, attr_name, timeout), timeout)

    def wait_for_text_not_present_in_element(self, locator, text, timeout=60):
        self._until_not(EC.text_to_be_present_in_element(locator, text), timeout)

    def wait_for_text_present_in_element(self, locator, text, timeout=60):
        self._until(EC.text_to_be_present_in_element(locator, text), timeout)

    def get_fields_info_from_row(self, row_xpath, timeout):
        info_list = []
        self._wait_for_element_by((By.XPATH, row_xpath), timeout)
        for elem in self.driver.find_elements_by_xpath(row_xpath):
            info_list.append(elem.text.strip())
        return info_list

    def wait_until_element_is_clickable(self, xpath, timeout):
        try:
            self._until(EC.element_to_be_clickable((By.XPATH, xpath)), timeout)
        except TimeoutException:
            msg = 'Element with given xpath: {0} has not been able to click'.format(xpath)
            raise TimeoutException(msg)


class WebDriver(object):
    _driver = None
    _instance = None
    _download_dir = None
    _downloader = None
    _debug_dir = None

    def __new__(cls, *args, **kw):
        if not cls._instance:
            cls._instance = super(WebDriver, cls).__new__(cls)
        return cls._instance

    def __init__(self, download_dir=None, screenshot_dir=None):
        if not self._download_dir:
            self._downloader = Downloader()

            if download_dir and download_dir != '/':
                self._download_dir = download_dir
            else:
                self._download_dir = tempfile.mkdtemp(suffix="taf_selenium_coam_download")

            if screenshot_dir:
                self._create_debug_dir(screenshot_dir)
            else:
                self._create_debug_dir(self._download_dir)

    def _create_debug_dir(self, dir_path):
        self._debug_dir = os.path.join(dir_path, "taf_selenium_coam_screenshot")
        if not os.path.exists(self._debug_dir):
            os.makedirs(self._debug_dir)

    @property
    def driver(self):
        if not self._driver:
            self._driver = CustomWebdriver(self._download_dir)
        return self._driver

    @property
    def download_dir(self):
        return self._download_dir

    @property
    def downloader(self):
        return self._downloader

    @property
    def debug_dir(self):
        return self._debug_dir

    def close(self):
        self._download_dir = None
        self.driver.quit()
        self._driver = None
